mapper.insert:
INSERT INTO daily_price (
    product_code, price_date, price
) VALUES (#{productCode}, #{priceDate}, #{price})

mapper.select:
select count(*)
from daily_price
where product_code = #{productCode}
and price_date = #{priceDate}

SELECT product_code
FROM product
WHERE item_name = #{itemName}
  AND kind_name = #{kindName}

SELECT price_date
FROM daily_price
WHERE product_code = #{productCode}
  AND price_date BETWEEN #{startDate} AND #{endDate}

SELECT EXISTS (
    SELECT 1
    FROM daily_price
    WHERE product_code = #{product.productCode}
      AND price_date = #{priceDate}
)
